class ThroneInheritance:
    def __init__(self, kingName: str):
        # Each parent maps to ordered children list
        self.family = {}
        self.king = kingName
        self.dead = set()
        self.family[kingName] = []

    def birth(self, parentName: str, childName: str) -> None:
        if parentName not in self.family:
            self.family[parentName] = []
        self.family[parentName].append(childName)
        self.family[childName] = []

    def death(self, name: str) -> None:
        self.dead.add(name)

    def getInheritanceOrder(self) -> list[str]:
        order = []
        stack = [self.king]  # iterative preorder DFS (avoids recursion limit on deep trees)
        while stack:
            name = stack.pop()
            if name not in self.dead:
                order.append(name)
            stack.extend(reversed(self.family.get(name, [])))
        return order
